/**
 * Resource-format tests.
 *
 * Because proprietary game assets must not be redistributed, every fixture here is generated by
 * this repository's own builders (packages/mu-formats/src/testing/fixtures.ts), which implement the
 * *writing* side of each container. The tests therefore prove reader/writer symmetry for the format
 * structures. Conformance with real game data is tracked separately in docs/ASSET_PIPELINE.md and
 * requires the user's local data directory (see NEXT_TASK).
 */

import assert from 'node:assert/strict';
import test from 'node:test';

import {
  BUX_CODE,
  decryptFileCryptor,
  encryptFileCryptor,
  xorBuxMask,
} from '../crypto/file-cryptor.js';
import { BMD_LEA_KEY, createLea256EcbDecrypt } from '../crypto/lea256.js';
import { CIPHER_NAMES, decryptModulusCryptor, modulusCryptorMagic, UnsupportedCipherError } from '../crypto/modulus-cryptor.js';
import { parseBmd, extractMeshGeometry, summarizeBmd, bmdEulerToQuaternion } from '../format/bmd.js';
import { decodeDds, decodeOzb, decodeOzt, decodeTga, detectTextureFormat, inspectOzj } from '../format/texture.js';
import { countFlag, parseAtt, parseMap, parseObj, parseTerrainHeight, TILE_COUNT, TwFlags } from '../format/terrain.js';
import {
  buildAttFixture,
  buildBmdFixture,
  buildDdsFixture,
  buildMapFixture,
  buildObjFixture,
  buildOzbFixture,
  buildOzjFixture,
  buildOztFixture,
  buildTgaFixture,
} from '../testing/fixtures.js';

test('FileCryptor encrypt/decrypt are exact inverses', () => {
  const plain = new Uint8Array(4096);
  for (let i = 0; i < plain.length; i++) plain[i] = (i * 37 + 11) & 0xff;
  const encrypted = encryptFileCryptor(plain);
  assert.notEqual(Buffer.from(encrypted).toString('hex'), Buffer.from(plain).toString('hex'));
  assert.equal(Buffer.from(decryptFileCryptor(encrypted)).toString('hex'), Buffer.from(plain).toString('hex'));
});

test('Bux mask is its own inverse and restarts per record when requested', () => {
  const data = new Uint8Array([1, 2, 3, 4, 5, 6, 7]);
  const masked = xorBuxMask(data);
  assert.deepEqual([...masked], [1 ^ 0xfc, 2 ^ 0xcf, 3 ^ 0xab, 4 ^ 0xfc, 5 ^ 0xcf, 6 ^ 0xab, 7 ^ 0xfc]);
  assert.deepEqual([...xorBuxMask(masked)], [...data]);
  assert.deepEqual([...BUX_CODE], [0xfc, 0xcf, 0xab]);
});

test('LEA-256 encryption and decryption round-trip through the v15 container', () => {
  const fixture = buildBmdFixture({ version: 15, name: 'lea-roundtrip' });
  const payloadSize = new DataView(fixture.bytes.buffer, fixture.bytes.byteOffset).getInt32(4, true);
  assert.equal(payloadSize % 16, 0, 'v15 payload must be block aligned');

  // Decrypting the container payload with the LEA helper must not change the plaintext that the
  // BMD reader observes: both paths are exercised by the v15 test below. Here we additionally
  // check that the helper actually transforms the bytes (i.e. the fixture really is encrypted).
  const encryptedPayload = fixture.bytes.subarray(8, 8 + payloadSize);
  const decrypted = createLea256EcbDecrypt(BMD_LEA_KEY)(encryptedPayload);
  assert.notEqual(
    Buffer.from(encryptedPayload).toString('hex'),
    Buffer.from(decrypted).toString('hex'),
    'the v15 payload must be encrypted on disk',
  );
  assert.equal(String.fromCharCode(...decrypted.subarray(0, 4)), 'lea-');
});

test('ModulusCryptor container detection and unsupported algorithm reporting', () => {
  assert.equal(modulusCryptorMagic(new Uint8Array([0x41, 0x54, 0x54, 0x01])), 'ATT\u0001');
  assert.equal(modulusCryptorMagic(new Uint8Array([0x4d, 0x41, 0x50, 0x01])), 'MAP\u0001');
  assert.equal(modulusCryptorMagic(new Uint8Array([0x01, 0x02, 0x03, 0x04])), undefined);

  // algorithm byte 2 == CAST5 (not implemented yet) must fail with a diagnosable error
  const container = new Uint8Array(64);
  container[0] = 2; // algorithm2 -> CAST5
  container[1] = 2; // algorithm1 -> CAST5
  assert.throws(
    () => decryptModulusCryptor(container),
    (error: unknown) => error instanceof UnsupportedCipherError && error.algorithmName === CIPHER_NAMES[2],
  );
  assert.throws(() => decryptModulusCryptor(new Uint8Array(8)), /too short/);
});

test('BMD v12 fixture: parser reproduces every field', () => {
  const fixture = buildBmdFixture({ version: 12 });
  const model = parseBmd(fixture.bytes);
  assert.equal(model.version, 12);
  assert.equal(model.name, fixture.name);
  assert.equal(model.meshes.length, 1);
  assert.equal(model.actions.length, 1);
  assert.equal(model.bones.length, 3);

  const mesh = model.meshes[0]!;
  assert.equal(mesh.textureIndex, 7);
  assert.equal(mesh.texturePath, fixture.mesh.texturePath);
  assert.equal(mesh.vertices.length, 4);
  mesh.vertices.forEach((vertex, index) => {
    const expected = fixture.mesh.vertices[index]!.position;
    assert.ok(Math.abs(vertex.position.x - expected[0]) < 1e-6, `vertex ${index} x`);
    assert.ok(Math.abs(vertex.position.y - expected[1]) < 1e-6, `vertex ${index} y`);
    assert.ok(Math.abs(vertex.position.z - expected[2]) < 1e-6, `vertex ${index} z`);
  });
  assert.deepEqual(mesh.vertices.map((v) => v.node), fixture.mesh.vertices.map((v) => v.node));
  assert.equal(mesh.normals[0]!.normal.y, 1);
  mesh.texCoords.forEach((texCoord, index) => {
    const expected = fixture.mesh.texCoords[index]!;
    assert.ok(Math.abs(texCoord.u - expected[0]) < 1e-6);
    assert.ok(Math.abs(texCoord.v - expected[1]) < 1e-6);
  });
  assert.equal(mesh.triangles.length, 2);
  assert.deepEqual(mesh.triangles[0]!.vertexIndex, [0, 1, 2]);
  assert.deepEqual(mesh.triangles[1]!.vertexIndex, [0, 2, 3, 0]);
  assert.equal(mesh.triangles[1]!.polygon, 4);

  assert.equal(model.actions[0]!.numAnimationKeys, 3);
  assert.equal(model.bones[0]!.name, 'Bip01');
  assert.equal(model.bones[0]!.parent, -1);
  assert.equal(model.bones[1]!.name, 'Bip01 Head');
  assert.equal(model.bones[1]!.parent, 0);
  assert.equal(model.bones[2]!.isDummy, true);
  // float32 storage means values come back with float32 precision
  assert.ok(Math.abs(model.bones[1]!.matrices[0]!.rotation[2]!.x - 0.2) < 1e-6);
});

test('BMD v15 fixture: the LEA-encrypted payload is readable', () => {
  const fixture = buildBmdFixture({ version: 15, name: 'lea-model' });
  const model = parseBmd(fixture.bytes);
  assert.equal(model.version, 15);
  assert.equal(model.name, 'lea-model');
  assert.equal(model.meshes[0]!.triangles.length, 2);
  assert.equal(model.bones[1]!.name, 'Bip01 Head');
});

test('BMD plain fixture (no container encryption) is readable', () => {
  const fixture = buildBmdFixture({ version: 0, name: 'plain-model' });
  const model = parseBmd(fixture.bytes);
  assert.equal(model.name, 'plain-model');
  assert.equal(model.encryptedPayloadSize, undefined);
});

test('BMD parser rejects malformed input instead of returning garbage', () => {
  const fixture = buildBmdFixture({ version: 0 });
  assert.throws(() => parseBmd(new Uint8Array([0x42, 0x4d])), /too small/);
  assert.throws(() => parseBmd(new Uint8Array([0x58, 0x4d, 0x44, 0])), /invalid BMD header/);
  const truncated = fixture.bytes.slice(0, 40);
  assert.throws(() => parseBmd(truncated), /truncated BMD|invalid/);
  const badCounts = fixture.bytes.slice();
  // mesh count is at offset 4 + 32 for the plain variant
  new DataView(badCounts.buffer).setUint16(36, 60000, true);
  assert.throws(() => parseBmd(badCounts), /invalid mesh count/);
});

test('BMD geometry extraction produces render-ready attributes', () => {
  const fixture = buildBmdFixture({ version: 12 });
  const model = parseBmd(fixture.bytes);
  const geometry = extractMeshGeometry(model.meshes[0]!);
  assert.equal(geometry.vertexCount, 7); // 3 + 4 corners
  assert.equal(geometry.triangleCount, 2);
  assert.equal(geometry.positions.length, 7 * 3);
  assert.equal(geometry.uvs.length, 7 * 2);
  assert.equal(geometry.skinIndices[0], 0);
  // the v coordinate is flipped for GPU textures
  assert.equal(geometry.uvs[1], 1);

  const rotation = bmdEulerToQuaternion({ x: 0, y: 0, z: 0 });
  assert.deepEqual(rotation, { w: 1, x: 0, y: 0, z: 0 });

  const summary = summarizeBmd(model);
  assert.equal(summary.meshes, 1);
  assert.equal(summary.triangles, 2);
  assert.equal(summary.vertices, 4);
  assert.deepEqual(summary.textures, ['Interface/test.tga']);
});

test('OZT decoding flips the stored bottom-up rows', () => {
  const fixture = buildOztFixture(4, 3);
  const image = decodeOzt(fixture.bytes);
  assert.equal(image.width, 4);
  assert.equal(image.height, 3);
  assert.equal(Buffer.from(image.rgba).toString('hex'), Buffer.from(fixture.pixels).toString('hex'));
});

test('OZT rejects truncated and mis-dimensioned files', () => {
  const fixture = buildOztFixture(4, 3);
  assert.throws(() => decodeOzt(fixture.bytes.slice(0, 30)), /truncated/);
  const broken = fixture.bytes.slice();
  new DataView(broken.buffer).setInt16(16, -1, true);
  assert.throws(() => decodeOzt(broken), /implausible dimensions/);
  const wrongDepth = fixture.bytes.slice();
  wrongDepth[20] = 16;
  assert.throws(() => decodeOzt(wrongDepth), /unsupported depth/);
});

test('OZB (BM6) decoding produces RGBA', () => {
  const fixture = buildOzbFixture(3, 2);
  const image = decodeOzb(fixture.bytes);
  assert.equal(image.width, 3);
  assert.equal(image.height, 2);
  assert.equal(Buffer.from(image.rgba).toString('hex'), Buffer.from(fixture.pixels).toString('hex'));
});

test('OZJ container information exposes the embedded JPEG window', () => {
  const payload = new Uint8Array([0xff, 0xd8, 0xff, 0xdb, 9, 9, 0xff, 0xd9]);
  const fixture = buildOzjFixture(payload);
  const info = inspectOzj(fixture.bytes);
  assert.equal(info.jpegOffset, fixture.jpegOffset);
  assert.equal(info.topDownSort, true);
  assert.equal(Buffer.from(info.jpeg).toString('hex'), Buffer.from(payload).toString('hex'));
  assert.throws(() => inspectOzj(new Uint8Array(64)), /JPEG marker not found/);
});

test('TGA decoding handles uncompressed and RLE payloads', () => {
  for (const rle of [false, true]) {
    const fixture = buildTgaFixture(2, 2, rle);
    const image = decodeTga(fixture.bytes);
    assert.equal(image.width, 2);
    assert.equal(image.height, 2);
    assert.equal(
      Buffer.from(image.rgba).toString('hex'),
      Buffer.from(fixture.pixels).toString('hex'),
      `mismatch for rle=${rle}`,
    );
  }
});

test('DDS DXT1 decoding handles the 4-colour and 3-colour modes', () => {
  const fixture = buildDdsFixture();
  const image = decodeDds(fixture.bytes);
  assert.equal(image.width, 4);
  assert.equal(image.height, 4);
  assert.deepEqual([...image.rgba.slice(0, 3)], fixture.expectedTopLeft);
  assert.equal(image.rgba[3], 255);

  const transparent = fixture.bytes.slice();
  const view = new DataView(transparent.buffer);
  view.setUint16(128, 0x0000, true); // colour0 = black
  view.setUint16(130, 0xffff, true); // colour1 = white -> 3-colour mode
  view.setUint32(132, 0xffffffff, true); // every pixel uses palette entry 3 -> transparent
  const image2 = decodeDds(transparent);
  assert.equal(image2.rgba[3], 0);
});

test('texture format detection works by extension and magic', () => {
  assert.equal(detectTextureFormat(new Uint8Array(4), 'foo/bar.OZJ'), 'ozj');
  assert.equal(detectTextureFormat(new Uint8Array(4), 'a.dds'), 'dds');
  assert.equal(detectTextureFormat(buildOzbFixture().bytes), 'ozb');
  const dds = buildDdsFixture().bytes;
  assert.equal(detectTextureFormat(dds), 'dds');
  assert.equal(detectTextureFormat(new Uint8Array([1, 2, 3, 4, 5])), undefined);
});

test('ATT fixture: attributes survive encryption and the Bux mask', () => {
  const fixture = buildAttFixture({ extended: true });
  const att = parseAtt(fixture.bytes);
  assert.equal(att.isExtended, true);
  assert.equal(att.cipher, 'filecryptor');
  assert.equal(att.index, 3);
  assert.equal(att.attributes.length, TILE_COUNT);
  assert.equal(Buffer.from(att.attributes.buffer, att.attributes.byteOffset, att.attributes.byteLength).toString('hex'),
    Buffer.from(fixture.attributes.buffer, fixture.attributes.byteOffset, fixture.attributes.byteLength).toString('hex'));
  assert.ok(countFlag(att.attributes, TwFlags.SafeZone) > 0);
  assert.ok(countFlag(att.attributes, TwFlags.NoMove) > 0);
  assert.ok(countFlag(att.attributes, TwFlags.Water) > 0);
});

test('ATT fixture: byte variant is detected by size', () => {
  const fixture = buildAttFixture({ extended: false });
  const att = parseAtt(fixture.bytes);
  assert.equal(att.isExtended, false);
  // tile 0 carries SafeZone|NoMove|Water (0x0015); the byte variant keeps only the low byte
  assert.equal(att.attributes[0], 0x15);
});

test('ATT parser rejects unexpected sizes', () => {
  assert.throws(() => parseAtt(new Uint8Array(100)), /unexpected size/);
});

test('MAP fixture: both texture layers and the blend map survive decryption', () => {
  const fixture = buildMapFixture();
  const map = parseMap(fixture.bytes);
  assert.equal(map.cipher, 'filecryptor');
  assert.equal(map.mapNumber, 3);
  assert.equal(map.layer1.length, TILE_COUNT);
  assert.equal(Buffer.from(map.layer1).toString('hex'), Buffer.from(fixture.layer1).toString('hex'));
  assert.equal(Buffer.from(map.layer2).toString('hex'), Buffer.from(fixture.layer2).toString('hex'));
  assert.equal(Buffer.from(map.alpha).toString('hex'), Buffer.from(fixture.alpha).toString('hex'));
});

test('OBJ fixture: object records survive decryption', () => {
  const fixture = buildObjFixture();
  const obj = parseObj(fixture.bytes);
  assert.equal(obj.version, 0);
  assert.equal(obj.mapNumber, 3);
  assert.equal(obj.objects.length, 2);
  assert.equal(obj.objects[0]!.type, 5);
  assert.ok(Math.abs(obj.objects[0]!.position.x - 140.5) < 1e-6);
  assert.ok(Math.abs(obj.objects[0]!.position.y - 120.25) < 1e-6);
  assert.ok(Math.abs(obj.objects[1]!.scale - 1.25) < 1e-6);
});

test('height maps are validated by size', () => {
  const heights = new Uint8Array(TILE_COUNT);
  heights[0] = 5;
  const parsed = parseTerrainHeight(heights);
  assert.equal(parsed.heights[0], 5);
  assert.throws(() => parseTerrainHeight(new Uint8Array(1000)), /unexpected size/);
});
